# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
```

## Basic Pool Setup

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                    // Maximum connections in pool
  min: 2,                     // Minimum idle connections maintained
  idleTimeoutMillis: 30000,   // Close idle connections after 30s
  connectionTimeoutMillis: 5000, // Fail if can't connect within 5s

  // Query timeout (requires pg >= 8.x)
  statement_timeout: 10000,   // Kill queries running over 10s
  query_timeout: 10000,       // Timeout for query execution

  // SSL (for production)
  ssl: process.env.NODE_ENV === 'production' 
    ? { rejectUnauthorized: true, ca: process.env.DB_SSL_CERT }
    : false,
});

module.exports = pool;
```

## Pool Event Handlers

```javascript
// db/pool.js (continued)

// Log when new connections are created
pool.on('connect', (client) => {
  console.log('New client connected to PostgreSQL');

  // Set session-level settings on each new connection
  client.query('SET timezone = "UTC"');
});

// Log when connections are acquired from pool
pool.on('acquire', (client) => {
  console.log('Client acquired from pool');
});

// Critical: handle idle client errors to prevent crashes
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client:', err);
  // Don't exit - pool will handle reconnection
  // process.exit(-1) // Only if error is unrecoverable
});

// Log when connections are removed
pool.on('remove', (client) => {
  console.log('Client removed from pool');
});
```

## Query Helper with Error Handling

```javascript
// db/query.js
const pool = require('./pool');

/**
 * Execute a simple query
 */
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;

    console.log('Query executed', {
      text,
      duration: `${duration}ms`,
      rows: result.rowCount,
    });

    return result;
  } catch (err) {
    console.error('Query error:', {
      text,
      params,
      error: err.message,
      code: err.code,
    });
    throw err;
  }
}

/**
 * Execute queries within a transaction
 */
async function withTransaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // Always release back to pool
  }
}

/**
 * Execute with explicit client (for complex operations)
 */
async function withClient(callback) {
  const client = await pool.connect();

  try {
    return await callback(client);
  } finally {
    client.release();
  }
}

module.exports = { query, withTransaction, withClient };
```

## Usage Examples

```javascript
// routes/users.js
const { query, withTransaction } = require('../db/query');

// Simple query
async function getUser(id) {
  const { rows } = await query(
    'SELECT * FROM users WHERE id = $1',
    [id]
  );
  return rows[0] ?? null;
}

// Transaction example
async function transferFunds(fromId, toId, amount) {
  return withTransaction(async (client) => {
    // Both queries use same connection/transaction
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    const { rows } = await client.query(
      'INSERT INTO transfers (from_id, to_id, amount) VALUES ($1, $2, $3) RETURNING *',
      [fromId, toId, amount]
    );

    return rows[0];
  });
}
```

## Graceful Shutdown

```javascript
// server.js
const pool = require('./db/pool');

async function shutdown(signal) {
  console.log(`Received ${signal}, shutting down gracefully`);

  try {
    await pool.end(); // Wait for active queries, then close all connections
    console.log('Pool has ended');
    process.exit(0);
  } catch (err) {
    console.error('Error during pool shutdown:', err);
    process.exit(1);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

## Health Check

```javascript
// db/health.js
const pool = require('./pool');

async function checkDatabaseHealth() {
  const client = await pool.connect();

  try {
    const start = Date.now();
    await client.query('SELECT 1');
    const latency = Date.now() - start;

    return {
      status: 'healthy',
      latency: `${latency}ms`,
      pool: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    };
  } catch (err) {
    return {
      status: 'unhealthy',
      error: err.message,
    };
  } finally {
    client.release();
  }
}

module.exports = { checkDatabaseHealth };
```

## Key Configuration Guidelines

| Setting | Development | Production |
|---------|-------------|------------|
| `max` | 5-10 | 20-100 (based on DB limits) |
| `min` | 0-2 | 2-5 |
| `idleTimeoutMillis` | 10000 | 30000 |
| `connectionTimeoutMillis` | 5000 | 3000-5000 |
| `statement_timeout` | 30000 | 5000-10000 |

## Common Pitfalls to Avoid

```javascript
// ❌ WRONG: Client never released on error
async function badExample() {
  const client = await pool.connect();
  const result = await client.query('SELECT * FROM users'); // throws!
  client.release(); // Never reached
  return result;
}

// ✅ CORRECT: Always use try/finally
async function goodExample() {
  const client = await pool.connect();
  try {
    return await client.query('SELECT * FROM users');
  } finally {
    client.release(); // Always runs
  }
}

// ❌ WRONG: Using pool.query() inside a transaction
async function badTransaction() {
  const client = await pool.connect();
  await client.query('BEGIN');
  await pool.query('UPDATE ...'); // Different connection! Not in transaction!
  await client.query('COMMIT');
}
```

The most critical rules are: **always release clients in a `finally` block**, use `pool.query()` for simple queries, and only use `client.connect()` when you need transactions or multiple related queries on the same connection.
